// Order-3 IIR, TRANSPOSED feedforward chain: one multiply+add per stage
// (registered partial sums) + a tiny additive combinational chain + one
// register per stage to wrap up the pipeline (the long path -> lower Fmax).
module iir3_v9 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [15:0] r1;
  reg [15:0] r2;
  reg [15:0] r3;
  reg [15:0] y2;
  wire [31:0] acc = 37*x + r1 + ((9*y)>>4) + ((5*y2)>>4);
  always @(posedge clk) begin
    if (!rst_n) begin y<=0; y2<=0; r1<=0; r2<=0; r3<=0; end
    else begin
      y2 <= y;
      y <= acc[15:0];
      r3<=r2; r2<=r1; r1 <= (62*x + r2) & 16'hFFFF;
    end
  end
endmodule
